        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new ThemeAssetSlide(function (ThemeAssetSlide $slide, ?ThemeAssetCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new ThemeAssetCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
