        $this->logDebug("Count for Theme asset on adapter ");
        $span = $this->startSpan("Count for Theme asset on adapter");
        try {
            $entity->commitContentWith($this->store);
            $created = $this->conn->create($entity, $verify);
            $this->dispatch($entity);
            $this->changelog->recordChange('theme-asset', $entity->uid() ?? 'no-id', $entity->asPublicJson());
