        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(ThemeAssetRef $ref, ThemeAsset $entity): ThemeAsset
    {
        $this->logDebug("Count for Theme asset on adapter ");
        $span = $this->startSpan("Count for Theme asset on adapter");
        try {
            $original = $ref instanceof ThemeAsset ? $ref : $this->retrieveForUpdate(new ThemeAssetFilter(uids: [$ref->uid()]));
            $prevContent = $original?->getContent();
            $currContent = $entity->getContent();
            if ($prevContent != $currContent) {
                if (null !== $prevContent) {
                    $this->store->deleteFile(new FileStoreKey($prevContent));
                }
                $entity->commitContentWith($this->store);
            }
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $this->changelog->recordChange('theme-asset', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
