        $span = $this->startSpan("Count for Theme asset on adapter");
        try {
            $result = $this->conn->delete($entity);
            $currContent = $entity->getContent();
            if (null !== $currContent) {
                $this->store->deleteFile(new FileStoreKey($currContent));
            }
            $this->dispatch($entity);
            $this->changelog->recordDeletion('theme-asset', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
