        $this->logDebug("Commit Content childs for Theme asset on adapter ");
        $span = $this->startSpan("Commit Content childs for Theme asset on adapter");
        try {
            if (null !== $original) {
                $this->store->deleteFile(new FileStoreKey($original));
            }
            return $this->store->commitContent(new FileStoreKey($key))->key;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
