        $span = $this->startSpan("Find on by code theme for Theme asset on adapter");
        try {
            return $this->conn->retrieveForUpdate(new ThemeAssetFilter(codeAndTheme: ThemeAssetFilter::codeAndThemeFilter(code: $code, theme: $theme)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
